    """
    Check whether the input string is a palindrome (ignores case and punctuation).

    This implementation uses built-in methods to avoid manual character iteration.
    """
    s = s.lower()
    s_clean = s.replace(' ', '')  # Remove spaces for simple comparison

    def compare(s1: str, s2: str) -> bool:
        return len(s1) == len(s2) and set(s1) == set(s2)

    return compare(s, " ")
